function quickSelectedDrug(){if($('qdcDrug').value==='__other'){const name=$('qdcOtherName').value.trim();return name&&name.length<=100?{id:'__other',name,category:'other',knowledgeId:null}:null}return QUICK_DRUGS.find(d=>d.id===$('qdcDrug').value)||null;}
function quickPopulateDrugs(){const category=$('qdcCategory').value;const items=QUICK_DRUGS.filter(d=>category==='all'||d.category===category);$('qdcDrug').innerHTML='<option value="">— เลือกยา —</option>'+QUICK_CATEGORIES.map(g=>{const drugs=items.filter(d=>d.category===g.id);return drugs.length?`<optgroup label="${esc(g.label)}">${drugs.map(d=>`<option value="${esc(d.id)}">${esc(d.name)}</option>`).join('')}</optgroup>`:''}).join('')+'<option value="__other">ยาอื่น ๆ — กรอกชื่อเอง</option>';if(category==='other')$('qdcDrug').value='__other';}
