function openCalculator(name=''){bindQuickCalculator();const dialog=$('quickDrugCalculatorDialog');if(!dialog.open){quickCalculatorFocus=document.activeElement;quickReset();criReset();quickSetMode('single');const known=findDrug(name),drug=QUICK_DRUGS.find(d=>d.id===known?.id||canonical(d.name)===canonical(name));if(drug){$('qdcDrug').value=drug.id;quickDrugChanged(true);}else if(known?.group==='Inhalant'){$('qdcError').textContent='ยาดมสลบไม่ใช้สูตร mg/kg → mL ต่อครั้ง เปิดอ่านข้อมูลยาในคลังความรู้ได้';}}showDialog(dialog,$('qdcTitle'));dialog.scrollTop=0;}

// CRI uses prescribed mass/time rates, never the single-dose reference catalogue.
const CRI_UNITS=Object.freeze({'mg/kg/h':1,'mg/kg/min':60,'mcg/kg/h':0.001,'mcg/kg/min':0.06});
function calculateCRI({method='rate',weight,dose,doseUnit,concentration,concentrationUnit,finalVolume='',pumpRate='',pumpRateUnit='mL/h'}={}){
 const fail=(field,message)=>({ok:false,field,message}),w=quickNumber(weight),d=quickNumber(dose),c=quickNumber(concentration);
 if(!['rate','mix'].includes(method))return fail('method','เลือกวิธีคำนวณ CRI');
 if(w===null)return fail('weight','กรอกน้ำหนักมากกว่า 0 เป็น kg ใช้จุดทศนิยม');
 if(d===null)return fail('dose','กรอกอัตรายาที่สัตวแพทย์กำหนดมากกว่า 0');
 if(!Object.hasOwn(CRI_UNITS,doseUnit))return fail('doseUnit','เลือกหน่วยอัตรายา mg หรือ mcg ต่อ kg ต่อนาที/ชั่วโมง');
 if(c===null)return fail('concentration','กรอกความเข้มข้นจริงมากกว่า 0');
 if(!['mg','mcg'].includes(concentrationUnit))return fail('concentrationUnit','เลือกความเข้มข้น mg/mL หรือ mcg/mL');
 const doseMgKgHour=d*CRI_UNITS[doseUnit],drugMgHour=w*doseMgKgHour,stockMgMl=c*(concentrationUnit==='mcg'?0.001:1);
 if(![doseMgKgHour,drugMgHour,stockMgMl].every(v=>Number.isFinite(v)&&v>0))return fail('dose','ค่าที่กรอกอยู่นอกขอบเขตตัวเลขที่รองรับ');
 const hasVolume=String(finalVolume??'').trim()!=='',volume=hasVolume?quickNumber(finalVolume):null;
 if((hasVolume||method==='mix')&&volume===null)return fail('finalVolume','กรอกปริมาตรสุดท้ายหลังรวมยา มากกว่า 0 เป็น mL');
 let flow,concentrationMgMl,totalDrugMg=null,stockVolume=null,diluentVolume=null;
 if(method==='rate'){concentrationMgMl=stockMgMl;flow=drugMgHour/concentrationMgMl;if(volume!==null)totalDrugMg=volume*concentrationMgMl;}
 else{
  const pump=quickNumber(pumpRate);if(pump===null)return fail('pumpRate','กรอกอัตราปั๊มที่กำหนดมากกว่า 0');
  if(!['mL/h','mL/kg/h'].includes(pumpRateUnit))return fail('pumpRateUnit','เลือกอัตราปั๊ม mL/h หรือ mL/kg/h');
  flow=pumpRateUnit==='mL/kg/h'?pump*w:pump;concentrationMgMl=drugMgHour/flow;totalDrugMg=concentrationMgMl*volume;stockVolume=totalDrugMg/stockMgMl;
  if(![flow,concentrationMgMl,totalDrugMg,stockVolume].every(v=>Number.isFinite(v)&&v>0))return fail('pumpRate','ผลอยู่นอกขอบเขตตัวเลขที่รองรับ กรุณาตรวจค่าที่กรอก');
  // Permit only a floating-point rounding margin at the exact no-dilution boundary.
  if(stockVolume-volume>Math.max(stockVolume,volume)*Number.EPSILON*8)return fail('finalVolume','ปริมาตรยาต้นขวดเกินปริมาตรสุดท้ายที่กำหนด ผสมให้ได้ความเข้มข้นนี้ด้วยการเจือจางไม่ได้ กรุณาทบทวนอัตราปั๊ม ปริมาตร หรือความเข้มข้น');
  stockVolume=Math.min(stockVolume,volume);diluentVolume=volume-stockVolume;
 }
 const flowPerKgHour=flow/w,duration=volume===null?null:volume/flow,deliveredDose=concentrationMgMl*flow/w/CRI_UNITS[doseUnit];
 if(![flow,concentrationMgMl,flowPerKgHour,deliveredDose,...(duration===null?[]:[duration]),...(totalDrugMg===null?[]:[totalDrugMg])].every(v=>Number.isFinite(v)&&v>0))return fail('dose','ผลอยู่นอกขอบเขตตัวเลขที่รองรับ กรุณาตรวจค่าที่กรอก');
 return {ok:true,method,weight:w,dose:d,doseUnit,concentration:c,concentrationUnit,doseMgKgHour,drugMgHour,stockMgMl,concentrationMgMl,flow,flowPerKgHour,finalVolume:volume,totalDrugMg,stockVolume,diluentVolume,duration,deliveredDose};
}
let criCalculation=null,criRevision=0;
