function criPopulateDrugs(){const category=$('criCategory').value,items=QUICK_DRUGS.filter(d=>category==='all'||d.category===category);$('criDrug').innerHTML='<option value="">— เลือกยา —</option>'+QUICK_CATEGORIES.map(g=>{const drugs=items.filter(d=>d.category===g.id);return drugs.length?`<optgroup label="${esc(g.label)}">${drugs.map(d=>`<option value="${esc(d.id)}">${esc(d.name)}</option>`).join('')}</optgroup>`:''}).join('')+'<option value="__other">ยาอื่น ๆ — กรอกชื่อเอง</option>';if(category==='other')$('criDrug').value='__other';}
