function quickSetMode(mode){const isCRI=mode==='cri';$('qdcSingle').hidden=isCRI;$('criPanel').hidden=!isCRI;$('qdcModeSingle').setAttribute('aria-pressed',String(!isCRI));$('qdcModeCRI').setAttribute('aria-pressed',String(isCRI));$('qdcTitle').textContent=isCRI?'คำนวณ CRI':'คำนวณยาเร็ว';}
function quickSwitchMode(mode){const current=$('criPanel').hidden?'single':'cri';if(current===mode)return;
 const isCRI=mode==='cri',drug=isCRI?quickSelectedDrug():criSelectedDrug(),species=$(isCRI?'qdcSpecies':'criSpecies').value,weight=$(isCRI?'qdcWeight':'criWeight').value;
 quickReset();criReset();const prefix=isCRI?'cri':'qdc';if(drug){$(prefix+'Drug').value=drug.id;if(drug.id==='__other')$(prefix+'OtherName').value=drug.name;$(prefix+'OtherNameWrap').hidden=drug.id!=='__other';}$(prefix+'Species').value=species;$(prefix+'Weight').value=weight;if(!isCRI)quickDrugChanged(false);
 quickSetMode(mode);$('qdcTitle').focus({preventScroll:true});$('quickDrugCalculatorDialog').scrollTop=0;
}
function criSubmit(e){e?.preventDefault();criClearResult();const drug=criSelectedDrug(),species=$('criSpecies').value,container=$('criContainer').value;
 const invalid=(field,message)=>{$('criError').textContent=message;const el=$('cri'+field[0].toUpperCase()+field.slice(1));el?.setAttribute('aria-invalid','true');el?.focus();};
 if(!drug){invalid($('criDrug').value==='__other'?'otherName':'drug','เลือกยาหรือกรอกชื่อยาอื่น ๆ ไม่เกิน 100 ตัวอักษร');return}if(!['dog','cat'].includes(species)){invalid('species','เลือกสุนัขหรือแมวเพื่อระบุผลคำนวณ');return}if(!['syringe','bag'].includes(container)){invalid('container','เลือก syringe pump หรือถุงสารน้ำ');return}
 const r=calculateCRI({method:$('criMethod').value,weight:$('criWeight').value,dose:$('criDose').value,doseUnit:$('criDoseUnit').value,concentration:$('criConcentration').value,concentrationUnit:$('criConcentrationUnit').value,finalVolume:$('criFinalVolume').value,pumpRate:$('criPumpRate').value,pumpRateUnit:$('criPumpRateUnit').value});if(!r.ok){invalid(r.field,r.message);return}
 const f=quickFormat,l=quickLiteral,animal=species==='dog'?'สุนัข':'แมว',kind=container==='syringe'?'syringe pump':'ถุงสารน้ำ',mix=r.method==='mix',basis=`${drug.name} · ${animal} · ${l($('criWeight').value)} kg · ${kind}`,ordered=`${l($('criDose').value)} ${r.doseUnit}`,prep=`${l($('criConcentration').value)} ${r.concentrationUnit}/mL`,volume=r.finalVolume===null?'':l($('criFinalVolume').value);
 const recipe=mix?`ปริมาตรสุดท้ายหลังรวมยา: ${volume} mL\nอัตราปั๊มที่กำหนด: ${l($('criPumpRate').value)} ${$('criPumpRateUnit').value}\nตัวยารวมในภาชนะ: ≈ ${f(r.totalDrugMg)} mg\nปริมาตรยาต้นขวด: ≈ ${f(r.stockVolume)} mL\nตัวเจือจาง: ≈ ${f(r.diluentVolume)} mL\nความเข้มข้นสุดท้าย: ≈ ${f(r.concentrationMgMl)} mg/mL`:(volume?`ปริมาตรที่เตรียมแล้ว: ${volume} mL`:'ไม่ได้ระบุปริมาตรที่เตรียมแล้ว');
 const caution='ผลจากอัตราที่กรอก ไม่เลือกโดส CRI ไม่รวม loading dose/การ prime สาย ไม่ใช่บันทึกการให้ยา ตรวจผู้ป่วย ฉลาก ความเข้ากันได้ ความคงตัว และช่วงอัตราที่ปั๊มรองรับก่อนใช้';
 criCalculation={...r,name:drug.name,species,container,text:`ANESVET · คำนวณ CRI\n${basis}\nวิธี: ${mix?'เตรียมยาที่อัตราปั๊มกำหนด':'หาอัตราปั๊มจากยาที่เตรียมแล้ว'}\nอัตรายาที่กรอก: ${ordered}\n${mix?'ความเข้มข้นยาต้นขวด':'ความเข้มข้นหลังเตรียมยา'}: ${prep}\n${recipe}\nอัตราปั๊ม: ≈ ${f(r.flow)} mL/h\nอัตราปริมาตรต่อน้ำหนัก: ≈ ${f(r.flowPerKgHour)} mL/kg/h\nตัวยาต่อชั่วโมง: ≈ ${f(r.drugMgHour)} mg/h\nตรวจกลับ: ≈ ${f(r.deliveredDose)} ${r.doseUnit}\n${r.duration===null?'':`ระยะเวลาตามปริมาตร: ≈ ${f(r.duration)} ชั่วโมง\n`}${mix?'หากเปลี่ยนอัตราสารน้ำ/ปั๊ม อัตรายาที่ผู้ป่วยได้รับเปลี่ยนด้วย ต้องคำนวณใหม่\n':''}${caution}`};
 $('criResult').innerHTML=`<p class="ck-meta">${esc(basis)}</p><p><b>${mix?'เตรียมยาที่อัตราปั๊มกำหนด':'หาอัตราปั๊มจากยาที่เตรียมแล้ว'}</b></p><div class="qdc-result-grid"><div><span>อัตราปั๊มที่คำนวณได้</span><strong>≈ ${f(r.flow)} <small>mL/h</small></strong></div><div><span>ตัวยาต่อชั่วโมง</span><strong>≈ ${f(r.drugMgHour)} <small>mg/h</small></strong></div></div><p>อัตราที่กรอก: <b>${esc(ordered)}</b><br>${mix?'ความเข้มข้นยาต้นขวด':'ความเข้มข้นหลังเตรียมยา'}: <b>${esc(prep)}</b></p>${mix?`<section class="cri-recipe"><h3>ส่วนผสมสำหรับปริมาตรสุดท้าย ${esc(volume)} mL</h3><p><b>ยาต้นขวด ≈ ${f(r.stockVolume)} mL</b><br>ตัวเจือจาง ≈ ${f(r.diluentVolume)} mL<br>ตัวยารวม ≈ ${f(r.totalDrugMg)} mg<br>ความเข้มข้นสุดท้าย ≈ ${f(r.concentrationMgMl)} mg/mL</p><p class="ck-meta">รวมแล้ว ${esc(volume)} mL · หากเริ่มจากถุง/ภาชนะเต็ม ต้องปรับปริมาตรก่อนเติมยาให้ได้ปริมาตรสุดท้ายนี้ และตรวจปริมาตรจริง</p><p class="ck-note">หากเปลี่ยนอัตราสารน้ำหรือปั๊ม อัตรายาที่ได้รับจะเปลี่ยนด้วย ต้องคำนวณใหม่ ไม่ใช้ถุงที่ผสมยานี้ให้สารน้ำ bolus</p></section>`:''}<p>อัตราปริมาตร ≈ ${f(r.flowPerKgHour)} mL/kg/h<br><b>ตรวจกลับ: ≈ ${f(r.deliveredDose)} ${esc(r.doseUnit)}</b>${r.duration===null?'':`<br>ระยะเวลาตามปริมาตร ≈ ${f(r.duration)} ชั่วโมง · ไม่ตั้งเวลาหรือคำนวณปริมาตรคงเหลือหลัง prime`}</p><details><summary>ดูสูตรและการแปลงหน่วย</summary><p>อัตราที่กรอก × ตัวแปลงหน่วย ${CRI_UNITS[r.doseUnit]} = ${f(r.doseMgKgHour)} mg/kg/h</p><p>${f(r.doseMgKgHour)} mg/kg/h × ${f(r.weight)} kg = ${f(r.drugMgHour)} mg/h</p><p>อัตราปั๊ม = ${f(r.drugMgHour)} mg/h ÷ ${f(r.concentrationMgMl)} mg/mL = ≈ ${f(r.flow)} mL/h</p>${mix?`<p>ความเข้มข้นเป้าหมาย = ${f(r.drugMgHour)} mg/h ÷ ${f(r.flow)} mL/h<br>ตัวยารวม = ความเข้มข้นเป้าหมาย × ${esc(volume)} mL<br>ยาต้นขวด = ${f(r.totalDrugMg)} mg ÷ ${f(r.stockMgMl)} mg/mL</p>`:''}<p>ตรวจกลับ = ความเข้มข้นสุดท้าย × mL/h ÷ น้ำหนัก แล้วแปลงเป็นหน่วยอัตราที่กรอก</p><p class="ck-meta">1 mg = 1,000 mcg (µg) · 1 ชั่วโมง = 60 นาที · แสดงประมาณ 10 หลักนัยสำคัญ ไม่ปัดตามอุปกรณ์</p></details><p class="ck-note">${esc(caution)}</p>`;
 $('criResult').hidden=false;$('criCopy').disabled=false;$('criResult').focus({preventScroll:true});$('criResult').scrollIntoView({block:'start'});
}
async function criCopy(){if(!criCalculation)return;const text=criCalculation.text,revision=criRevision;try{if(!navigator.clipboard?.writeText)throw new Error('Clipboard unavailable');await navigator.clipboard.writeText(text);if(revision===criRevision)$('criStatus').textContent='คัดลอกผล CRI และค่าที่กรอกแล้ว';}catch(_){if(revision!==criRevision)return;$('criCopyFallback').hidden=false;$('criCopyText').value=text;$('criCopyText').focus();$('criCopyText').select();$('criStatus').textContent='คัดลอกอัตโนมัติไม่ได้ เลือกและคัดลอกข้อความด้านล่างได้';}}
function bindCRI(){
 $('criPanel').innerHTML=`<p class="qdc-intro">คำนวณยาทีละชนิดสำหรับ syringe pump หรือถุงสารน้ำ · ใช้อัตรา CRI ที่สัตวแพทย์กำหนด</p><form id="criForm" novalidate><div class="qdc-grid"><label class="qdc-wide" for="criMethod">วิธีคำนวณ<select id="criMethod" class="session-safe"><option value="rate">ยาที่เตรียมแล้ว → หาอัตราปั๊ม mL/h</option><option value="mix">เตรียมส่วนผสมตามอัตราปั๊มที่กำหนด</option></select></label><label class="qdc-wide" for="criCategory">1. หมวดยา<select id="criCategory" class="session-safe"><option value="all">ทั้งหมด</option>${QUICK_CATEGORIES.map(c=>`<option value="${esc(c.id)}">${esc(c.label)}</option>`).join('')}<option value="other">อื่น ๆ — กรอกชื่อเอง</option></select></label><label class="qdc-wide" for="criDrug">ชื่อยา<select id="criDrug" class="session-safe"></select></label><label id="criOtherNameWrap" class="qdc-wide" for="criOtherName" hidden>ชื่อยาอื่น ๆ<input id="criOtherName" class="session-safe" maxlength="100" type="text" autocomplete="off"></label><label for="criSpecies">ชนิดสัตว์<select id="criSpecies" class="session-safe"><option value="">— เลือก —</option><option value="dog">สุนัข</option><option value="cat">แมว</option></select></label><label for="criWeight">2. น้ำหนักที่ใช้คำนวณ (kg)<input id="criWeight" class="session-safe" type="text" inputmode="decimal" autocomplete="off" placeholder="กรอกน้ำหนัก"></label><label class="qdc-wide" for="criContainer">ภาชนะที่ใช้<select id="criContainer" class="session-safe"><option value="">— เลือก —</option><option value="syringe">Syringe pump</option><option value="bag">ถุงสารน้ำ</option></select></label><div class="qdc-wide qdc-pair cri-unit-pair"><label for="criDose">3. อัตรา CRI ที่กำหนด<input id="criDose" class="session-safe" type="text" inputmode="decimal" autocomplete="off" placeholder="ไม่ใช่โดสต่อครั้ง"></label><label for="criDoseUnit">หน่วยอัตรายา<select id="criDoseUnit" class="session-safe"><option value="">— เลือกหน่วย —</option>${Object.keys(CRI_UNITS).map(u=>`<option value="${u}">${u}</option>`).join('')}</select></label></div><p class="ck-meta qdc-wide">mcg = µg · ไม่ดึงโดสต่อครั้งจาก Dose Reference มาเป็นอัตรา CRI</p><div class="qdc-wide qdc-pair"><label for="criConcentration"><span id="criConcentrationLabel"></span><input id="criConcentration" class="session-safe" type="text" inputmode="decimal" autocomplete="off" placeholder="ความเข้มข้นจริงตามฉลาก / หลังเตรียม"></label><label for="criConcentrationUnit">หน่วยความเข้มข้น<select id="criConcentrationUnit" class="session-safe"><option value="">— เลือก —</option><option value="mg">mg/mL</option><option value="mcg">mcg/mL (µg/mL)</option></select></label></div><label class="qdc-wide" for="criFinalVolume"><span id="criVolumeLabel"></span><input id="criFinalVolume" class="session-safe" type="text" inputmode="decimal" autocomplete="off" aria-describedby="criVolumeHelp"></label><p id="criVolumeHelp" class="ck-meta qdc-wide"></p><div id="criMixFields" class="qdc-wide qdc-pair cri-unit-pair" hidden><label for="criPumpRate">6. อัตราปั๊ม / สารน้ำที่กำหนด<input id="criPumpRate" class="session-safe" type="text" inputmode="decimal" autocomplete="off" placeholder="อัตราที่ผู้ดูแลกำหนด"></label><label for="criPumpRateUnit">หน่วยอัตราปริมาตร<select id="criPumpRateUnit" class="session-safe"><option value="">— เลือก —</option><option value="mL/h">mL/h</option><option value="mL/kg/h">mL/kg/h</option></select></label></div></div><p class="ck-meta">ใช้จุดทศนิยม · 1 mg = 1,000 mcg · 1 ชั่วโมง = 60 นาที</p><p id="criError" class="qdc-error" role="alert"></p><div class="qdc-actions"><button id="criCalculate" type="submit" class="btn primary session-safe">คำนวณ</button><button id="criReset" type="button" class="btn session-safe">ล้างค่า CRI</button></div></form><section id="criResult" class="qdc-result" tabindex="-1" aria-label="ผลคำนวณ CRI จากค่าที่กรอก" hidden></section><div class="qdc-actions"><button id="criCopy" type="button" class="btn session-safe" disabled>คัดลอกผล CRI พร้อมค่าที่กรอก</button></div><p id="criStatus" class="ck-meta" role="status" aria-live="polite"></p><label id="criCopyFallback" class="qdc-copy" hidden>ข้อความผล CRI<textarea id="criCopyText" class="session-safe" readonly rows="12"></textarea></label><details class="ck-entry"><summary>วิธีใช้ CRI และแหล่งตรวจสูตร</summary><p>ใช้ความเข้มข้นหลังเตรียมยาในโหมดหาอัตราปั๊ม; ใช้ความเข้มข้นยาต้นขวดในโหมดเตรียมส่วนผสม</p><p>ปริมาตรสุดท้าย = ยาต้นขวด + ตัวเจือจาง ตรวจปริมาตรจริง ไม่อาศัยเลขหน้าถุงหากมี overfill หรือมีการเติมยาอื่น</p><p>คำนวณทีละยา ไม่ตรวจความเข้ากันได้ของยาหลายชนิดหรือสารน้ำ ไม่คำนวณ loading dose, IU, mEq, %, จำนวนเม็ด หรือจำนวนหยดต่อนาที</p><p>ตรวจความเข้ากันได้ ความคงตัว ภาระสารน้ำ ช่วงอัตราปั๊ม และแผนการติดตามผู้ป่วยแยกกัน</p><p><a href="https://www.canadianveterinarians.net/media/hhlgn5sl/constant-rate-infusions-2023.pdf" target="_blank" rel="noopener noreferrer">Tamara Grubb · Constant Rate Infusions · สูตรและหน่วย หน้าไฟล์ 2 ↗</a></p><p><a href="https://www.aaha.org/resources/2024-aaha-fluid-therapy-guidelines-for-dogs-and-cats/fluid-therapy-frequently-asked-questions/" target="_blank" rel="noopener noreferrer">AAHA 2024 · Fluid Therapy FAQ / การใช้ปั๊ม ↗</a></p><p class="ck-meta">ตรวจต้นทาง 2026-10-11 · การตรวจซอฟต์แวร์ไม่ใช่การรับรองโดสหรือสูตรผสมทางคลินิก</p></details><p class="ck-note">ไม่เลือกโดส CRI ให้ผู้ใช้ · ไม่บันทึกการให้ยาในเคส เมื่อเปลี่ยนยา ชนิดสัตว์ หรือวิธีคำนวณ ต้องกรอกอัตราและความเข้มข้นใหม่</p>`;
 $('criForm').addEventListener('submit',criSubmit);$('criForm').addEventListener('input',criClearResult);$('criForm').addEventListener('change',criClearResult);$('criMethod').addEventListener('change',()=>criMethodChanged());$('criCategory').addEventListener('change',()=>{criPopulateDrugs();criIdentityChanged(true);if($('criDrug').value==='__other')$('criOtherName').focus()});$('criDrug').addEventListener('change',()=>{criIdentityChanged(true);if($('criDrug').value==='__other')$('criOtherName').focus()});$('criOtherName').addEventListener('input',()=>criIdentityChanged(false));$('criSpecies').addEventListener('change',()=>criClearRates());$('criContainer').addEventListener('change',criClearResult);$('criReset').addEventListener('click',()=>{criReset();$('criDrug').focus()});$('criCopy').addEventListener('click',criCopy);criReset();
}
